-- Campaign deletion cascades. Check scope of every affected linked object.
begin;
set local lock_timeout='3s';
set local statement_timeout='30s';
do $$declare body text;patched text;gate text;begin
 if not exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.mkt_delete_campaign(uuid,text)') and p.prosecdef and md5(replace(p.prosrc,chr(13),''))='bfd58c1c9846041aed4537f1092b8fdf') then raise exception 'MKT_CAMPAIGN_DELETE_BASELINE_CHANGED';end if;
 select replace(pg_get_functiondef('public.mkt_delete_campaign(uuid,text)'::regprocedure),chr(13),'') into body;
 gate:='  if not public.user_has_permission(v_actor, ''mkt.manage_campaigns'') then' || chr(10) || '    raise exception ''INSUFFICIENT_ROLE'' using errcode = ''P0001'';' || chr(10) || '  end if;';
 patched:=replace(body,gate,'');if patched=body then raise exception 'MKT_CAMPAIGN_DELETE_GATE_CHANGED';end if;body:=patched;
 patched:=replace(body,'  -- An toàn: không xoá thẳng chiến dịch đang chạy',
  '  perform 1 from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null order by t.id for update;' || chr(10) ||
  '  perform 1 from public.mkt_channel_plans p where p.tenant_id=v_tenant and p.campaign_id=p_campaign_id and p.deleted_at is null order by p.id for update;' || chr(10) ||
  '  perform 1 from public.mkt_content_items ci where ci.tenant_id=v_tenant and (ci.campaign_id=p_campaign_id or ci.id in (select t.content_item_id from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null)) order by ci.id for update;' || chr(10) ||
  '  perform 1 from public.mkt_channel_work_packages w where w.tenant_id=v_tenant and (w.campaign_id=p_campaign_id or w.id in (select p.work_package_id from public.mkt_channel_plans p where p.tenant_id=v_tenant and p.campaign_id=p_campaign_id and p.deleted_at is null union select t.work_package_id from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null union select ci.work_package_id from public.mkt_content_items ci where ci.tenant_id=v_tenant and (ci.campaign_id=p_campaign_id or ci.id in (select t.content_item_id from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null)))) order by w.id for update;' || chr(10) ||
  '  perform 1 from public.mkt_campaigns c where c.tenant_id=v_tenant and c.id in (select ci.campaign_id from public.mkt_content_items ci where ci.tenant_id=v_tenant and (ci.campaign_id=p_campaign_id or ci.id in (select t.content_item_id from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null)) union select w.campaign_id from public.mkt_channel_work_packages w where w.tenant_id=v_tenant and (w.campaign_id=p_campaign_id or w.id in (select p.work_package_id from public.mkt_channel_plans p where p.tenant_id=v_tenant and p.campaign_id=p_campaign_id and p.deleted_at is null union select t.work_package_id from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null union select ci.work_package_id from public.mkt_content_items ci where ci.tenant_id=v_tenant and (ci.campaign_id=p_campaign_id or ci.id in (select t.content_item_id from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null))))) order by c.id for update;' || chr(10) ||
  '  if not public._staff_mkt_campaign_permission(v_actor,''mkt.manage_campaigns'',p_campaign_id) or exists(select 1 from public.mkt_tasks t where t.tenant_id=v_tenant and t.campaign_id=p_campaign_id and t.deleted_at is null and not public._staff_mkt_linked_permission(v_actor,''mkt.manage_campaigns'',t.campaign_id,t.work_package_id,t.content_item_id,null)) or exists(select 1 from public.mkt_channel_plans p where p.tenant_id=v_tenant and p.campaign_id=p_campaign_id and p.deleted_at is null and not public._staff_mkt_linked_permission(v_actor,''mkt.manage_campaigns'',null,null,null,p.id)) or exists(select 1 from public.mkt_content_items ci where ci.tenant_id=v_tenant and ci.campaign_id=p_campaign_id and ci.deleted_at is null and not public._staff_mkt_linked_permission(v_actor,''mkt.manage_campaigns'',null,null,ci.id,null)) then raise exception ''INSUFFICIENT_ROLE'' using errcode = ''P0001''; end if;' || chr(10) ||
  '  -- An toàn: không xoá thẳng chiến dịch đang chạy');
 if patched=body then raise exception 'MKT_CAMPAIGN_DELETE_SCOPE_CHANGED';end if;execute patched;
end$$;
commit;
